package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import java.lang.reflect.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.crypto.password.PasswordEncoder; import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
class EmailChangeVerificationServiceTest {
 ClienteDAO clientes=mock(ClienteDAO.class); EntrenadorDAO entrenadores=mock(EntrenadorDAO.class); PasswordEncoder passwords=mock(PasswordEncoder.class); RefreshTokenService refresh=mock(RefreshTokenService.class); EmailChangeTokenDAO tokens=mock(EmailChangeTokenDAO.class); PasswordResetTokenDAO resets=mock(PasswordResetTokenDAO.class); EmailChangeNotifier notifier=mock(EmailChangeNotifier.class); EmailChangeService service; Cliente user; UUID id=UUID.randomUUID();
 @BeforeEach void setup(){service=new EmailChangeService(clientes,entrenadores,passwords,refresh,tokens,resets,Optional.of(notifier),30);user=new Cliente();set(user,"id",id);user.setEmail("old@nextfit.test");user.setContrasena("hash");when(clientes.findById(id)).thenReturn(Optional.of(user));when(passwords.matches(anyString(),eq("hash"))).thenReturn(true);when(clientes.findByEmail(anyString())).thenReturn(Optional.empty());when(entrenadores.findByEmail(anyString())).thenReturn(Optional.empty());when(tokens.findByUserIdAndRoleAndConsumedAtIsNull(any(),any())).thenReturn(List.of());}
 @Test void invalidPasswordAndInvalidEmailDoNotCreateToken(){when(passwords.matches(anyString(),eq("hash"))).thenReturn(false);assertThrows(InvalidCurrentPasswordException.class,()->service.request(principal(),"bad","new@nextfit.test"));assertThrows(InvalidEmailException.class,()->service.request(principal(),"ok","bad"));verify(tokens,never()).save(any());verifyNoInteractions(notifier);assertEquals("old@nextfit.test",user.getEmail());}
 @Test void validRequestDoesNotChangeEmailAndPersistsOnlyHash(){ArgumentCaptor<EmailChangeToken> stored=ArgumentCaptor.forClass(EmailChangeToken.class);ArgumentCaptor<String> raw=ArgumentCaptor.forClass(String.class);service.request(principal(),"ok"," New@NextFit.Test ");verify(tokens).save(stored.capture());verify(notifier).notifyChange(eq("new@nextfit.test"),raw.capture());assertEquals("old@nextfit.test",user.getEmail());assertEquals("new@nextfit.test",stored.getValue().getNewEmail());assertNotEquals(raw.getValue(),stored.getValue().getTokenHash());assertEquals(PasswordResetService.hash(raw.getValue()),stored.getValue().getTokenHash());}
 @Test void confirmConsumesTokenRotatesOnlyOwnerAndBlocksReplay(){EmailChangeToken token=new EmailChangeToken(id,Role.CLIENTE,"new@nextfit.test",PasswordResetService.hash("raw"),Instant.now().plusSeconds(600),Instant.now());when(tokens.findByTokenHash(PasswordResetService.hash("raw"))).thenReturn(Optional.of(token));when(refresh.issue(any(),eq(ClientType.MOBILE))).thenReturn(new RefreshTokenService.IssuedToken("refresh","hash",UUID.randomUUID(),Instant.now().plusSeconds(1)));EmailChangeService.Result result=service.confirm("raw",ClientType.MOBILE);assertEquals("new@nextfit.test",result.user().email());assertNotNull(token.getConsumedAt());verify(refresh).revokeAllForUser(id,Role.CLIENTE);assertThrows(InvalidEmailChangeTokenException.class,()->service.confirm("raw",ClientType.MOBILE));}
 @Test void occupiedEmailAtConfirmDoesNotOverwrite(){EmailChangeToken token=new EmailChangeToken(id,Role.CLIENTE,"taken@nextfit.test",PasswordResetService.hash("raw"),Instant.now().plusSeconds(600),Instant.now());when(tokens.findByTokenHash(anyString())).thenReturn(Optional.of(token));when(clientes.findByEmail("taken@nextfit.test")).thenReturn(Optional.of(new Cliente()));assertThrows(EmailAlreadyInUseException.class,()->service.confirm("raw",ClientType.WEB));assertEquals("old@nextfit.test",user.getEmail());verifyNoInteractions(refresh);}
 private AuthenticatedUser principal(){return new AuthenticatedUser(id,"old@nextfit.test",Role.CLIENTE);} private static void set(Object o,String n,Object v){try{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}catch(Exception e){throw new RuntimeException(e);}}
}
